const fs = require('fs');
const https = require('https');

// Configuration
const API_URL = 'https://staging.crossmint.com/api/2022-06-09/collections/default/nfts';
const API_KEY = process.env.CROSSMINT_API_KEY;
const RECIPIENTS_FILE = '/home/user/recipients.json';
const SUMMARY_FILE = '/home/user/airdrop_summary.json';

// NFT Metadata
const NFT_METADATA = {
  name: 'Welcome NFT',
  description: 'Airdrop token',
  image: 'https://example.com/welcome.png'
};

// Make HTTPS request
function makeRequest(method, url, headers, data) {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(url);
    const options = {
      hostname: urlObj.hostname,
      path: urlObj.pathname + urlObj.search,
      method: method,
      headers: headers
    };

    const req = https.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        try {
          const parsedBody = body ? JSON.parse(body) : null;
          resolve({
            statusCode: res.statusCode,
            statusMessage: res.statusMessage,
            headers: res.headers,
            body: parsedBody
          });
        } catch (e) {
          resolve({
            statusCode: res.statusCode,
            statusMessage: res.statusMessage,
            headers: res.headers,
            body: body
          });
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    if (data) {
      req.write(JSON.stringify(data));
    }
    req.end();
  });
}

// Mint NFT to a recipient
async function mintNFT(email) {
  const recipient = `email:${email}:polygon-amoy`;

  const headers = {
    'Content-Type': 'application/json',
    'x-api-key': API_KEY
  };

  const payload = {
    recipient: recipient,
    metadata: NFT_METADATA
  };

  try {
    const response = await makeRequest('POST', API_URL, headers, payload);
    return response;
  } catch (error) {
    return {
      statusCode: null,
      statusMessage: error.message,
      body: { error: error.message }
    };
  }
}

// Main function
async function main() {
  if (!API_KEY) {
    console.error('Error: CROSSMINT_API_KEY environment variable is not set');
    process.exit(1);
  }

  // Read recipients file
  let recipients;
  try {
    const recipientsData = fs.readFileSync(RECIPIENTS_FILE, 'utf8');
    recipients = JSON.parse(recipientsData);

    if (!Array.isArray(recipients)) {
      console.error('Error: recipients.json must contain an array of email addresses');
      process.exit(1);
    }
  } catch (error) {
    console.error(`Error reading recipients file: ${error.message}`);
    process.exit(1);
  }

  if (recipients.length === 0) {
    console.log('No recipients found in recipients.json');
    fs.writeFileSync(SUMMARY_FILE, JSON.stringify({
      total: 0,
      results: []
    }, null, 2));
    return;
  }

  console.log(`Processing ${recipients.length} recipients...`);

  const results = [];

  for (const email of recipients) {
    console.log(`Minting to ${email}...`);

    const response = await mintNFT(email);

    const status = (response.statusCode === 200 || response.statusCode === 202) ? 'sent' : 'error';

    results.push({
      email: email,
      status: status,
      response: response.statusCode ? response : null
    });

    if (status === 'sent') {
      console.log(`  ✓ Success (${response.statusCode})`);
    } else {
      console.log(`  ✗ Failed (${response.statusCode || 'Network Error'}): ${response.statusMessage || response.body?.error || 'Unknown error'}`);
    }
  }

  // Write summary
  const summary = {
    total: recipients.length,
    results: results
  };

  fs.writeFileSync(SUMMARY_FILE, JSON.stringify(summary, null, 2));
  console.log(`\nSummary written to ${SUMMARY_FILE}`);

  // Print summary
  const sentCount = results.filter(r => r.status === 'sent').length;
  const errorCount = results.filter(r => r.status === 'error').length;
  console.log(`\nTotal: ${recipients.length}`);
  console.log(`Sent: ${sentCount}`);
  console.log(`Errors: ${errorCount}`);
}

// Run the script
main().catch(error => {
  console.error(`Fatal error: ${error.message}`);
  process.exit(1);
});

